raw:
{
  "core_conclusion": "A 문의는 발급/열람 여부와 채널에 따라 수수료가 달라지므로 확인이 필요하고, B 문의는 신청 시 요청하면 효력 있는 사항만 기재하여 발급받을 수 있습니다.",
  "missing_facts": [
    {
      "fact": "A 문의: 자동차등록원부를 발급받았는지 열람만 했는지, 그리고 인터넷/방문/무인발급기 중 어떤 채널을 이용했는지",
      "blocks_core_answer": true,
      "changes_answer": "발급(300원)인지 열람(100원)인지, 인터넷(무료)인지 방문/무인발급기(유료)인지에 따라 정확한 비용이 결정됩니다."
    }
  ],
  "can_answer_now": false,
  "question": "A 문의에 대해 정확한 비용을 안내해 드리기 위해 확인이 필요합니다. 자동차등록원부를 '발급'받았는지 '열람'만 했는지, 그리고 인터넷, 방문, 무인발급기 중 어떤 방법으로 이용하셨는지 알려주시겠어요? (B 문의는 신청 시 요청하면 효력 있는 사항만 기재하여 발급받을 수 있습니다.)"
}

{
  "core_conclusion": "A는 요구한 서류가 제적등본인지 제적초본인지 확인해야 하며, B는 가족 전원이 포함된 서류가 필요하므로 제적등본을 발급받아야 한다.",
  "missing_facts": [
    {
      "fact": "A가 제출을 요구받은 기관(또는 용도)이 명시적으로 '제적등본'인지 '제적초본'인지 구분하여 요구했는지 여부",
      "blocks_core_answer": true,
      "changes_answer": "요구받은 서류가 등본이면 초본 제출 시 반려될 수 있고, 초본이면 등본 제출 시 불필요한 개인정보 노출이나 비용 차이가 발생할 수 있어 정확한 서류명을 알려줄 수 없음"
    }
  ],
  "can_answer_now": false,
  "question": "A 문의에 대해, 서류를 제출하라고 한 기관이나 용도에서 '제적등본'과 '제적초본' 중 구체적으로 어느 것을 요구했는지 확인되나요? (예: 안내문에 '제적등본'이라고 적혀 있었는지 등)"
}

{
  "core_conclusion": "A 문의는 두 증명서의 정의 및 용도 차이를 설명하고, B 문의는 여권정보 공동이용 동의 여부에 따라 여권 지참 필요 여부를 판단한다.",
  "missing_facts": [
    {
      "fact": "B 문의에서 여권정보 공동이용 동의 화면에서 '동의' 버튼을 눌렀는지 또는 동의 완료 안내 문구가 떴는지 확인된 상태",
      "blocks_core_answer": true,
      "changes_answer": "동의가 완료된 상태라면 여권을 별도로 챙길 필요가 없고, 동의하지 않았거나 확인이 안 된 상태라면 여권을 지참해야 하므로 결론이 달라짐"
    }
  ],
  "can_answer_now": false,
  "question": "B 문의에 대해, 가족이 화면을 조작했을 때 여권정보 공동이용 동의 절차가 완료되었는지(동의 버튼 클릭 또는 완료 안내 문구 확인) 알 수 있나요?"
}

{
  "core_conclusion": "A 문의는 무인발급기 사용 가능 여부에 대한 확인, B 문의는 정당한 이해관계인 자격으로 가족관계증명서를 발급받기 위한 필요 서류 안내입니다.",
  "missing_facts": [
    {
      "fact": "A 문의에서 언급한 '이 화면'이 무인발급기 화면인지, 인터넷 발급 사이트 화면인지, 또는 방문 접수 창구 화면인지",
      "blocks_core_answer": true,
      "changes_answer": "무인발급기는 본인만 가능하여 자녀가 부모의 증명서를 발급받을 수 없으나, 인터넷 발급은 부모가 자녀의 증명서를 발급받을 수 있어 채널에 따라 가능 여부가 완전히 달라집니다."
    }
  ],
  "can_answer_now": false,
  "question": "A 문의에서 '이 화면'이라고 하신 것이 무인발급기 화면인지, 인터넷 발급 사이트 화면인지, 아니면 방문 접수 창구 화면인지 알려주세요."
}

{
  "core_conclusion": "A 문의는 아버지의 국외 체류 60일 도달 시점(사유 발생일)을 기준으로 다음 달부터 지급이 정지되며, B 문의는 주소지 관할이 아닌 지자체에 접수된 기초연금 신청서는 관할 지자체로 지체 없이 이송됩니다.",
  "missing_facts": [
    {
      "fact": "아버지가 해외로 출국한 정확한 날짜(또는 국외 체류가 60일이 되는 날)",
      "blocks_core_answer": true,
      "changes_answer": "법령상 '사유가 발생한 날(국외 체류 60일이 되는 날)이 속하는 달의 다음 달'부터 정지되므로, 출국일이 없으면 정지 시작 월을 특정할 수 없습니다."
    }
  ],
  "can_answer_now": false,
  "question": "아버지가 해외로 출국하신 정확한 날짜(또는 국외 체류 기간이 60일이 되는 날)를 알려주세요. B 문의의 경우 주소지 관할이 아닌 지자체에 접수된 신청서는 관할 지자체로 이송된다는 규정이 명확하여 추가 정보 없이 답변 가능합니다."
}

{
  "core_conclusion": "A는 전자등기사항증명서 발급 시 수수료 면제 제외 사유(등기기록상 주민등록번호 미기록 또는 명의 불일치) 중 어느 것에 해당하는지 확인이 필요하며, B는 초과 납부된 수수료의 환급 근거(수수료규칙 제6조 제4항)와 환급 포기 시 기재 사항(등기신청서 여백에 포기 취지 기재 및 기명날인 또는 서명)을 안내할 수 있습니다.",
  "missing_facts": [
    {
      "fact": "A의 등기기록에 주민등록번호(또는 부동산등기용등록번호)가 기록되어 있는지 여부",
      "blocks_core_answer": true,
      "changes_answer": "등기기록에 주민등록번호가 기록되어 있지 않은 경우(제15조의2 제1항 제1호)에는 면제 대상에서 제외되어 수수료가 부과됩니다. 기록되어 있다면 명의 일치 여부를 확인해야 합니다."
    },
    {
      "fact": "A의 발급 신청인 성명 및 주민등록번호(또는 부동산등기용등록번호)가 등기기록상 소유권 등기명의인의 정보와 일치하는지 여부",
      "blocks_core_answer": true,
      "changes_answer": "등기기록상 명의인의 정보와 신청인의 정보가 일치하지 않는 경우(제15조의2 제1항 제2호)에는 면제 대상에서 제외되어 수수료가 부과됩니다. 일치한다면 다른 사유(예: 시스템 오류 등)를 확인해야 하므로 결론이 달라집니다."
    }
  ],
  "can_answer_now": false,
  "question": "A 문의에 대해, 전자등기사항증명서 발급 시 수수료가 면제되지 않은 사유를 정확히 짚어드리기 위해 두 가지를 확인해 주세요. 1) 해당 부동산의 등기기록에 소유자의 주민등록번호(또는 부동산등기용등록번호)가 기록되어 있나요? 2) 발급을 신청하신 분의 성명과 주민등록번호(또는 부동산등기용등록번호)가 등기기록에 적힌 소유권 등기명의인의 정보와 완전히 일치하나요?"
}

{
  "core_conclusion": "A 문의는 발급된 확인서에 행위제한 내용이 없는 것이 누락인지 확인하려면 해당 토지의 실제 규제 현황과 신청 시 제외 옵션 체크 여부를 알아야 하며, B 문의는 토지이용계획확인서의 법정 처리기간은 '총 1일'이므로 등본의 '3시간' 기준과 다릅니다.",
  "missing_facts": [
    {
      "fact": "A 문의: 발급받은 토지이용계획확인서에 표시된 토지 소재지(또는 지번)와 해당 토지에 적용되는 지역·지구 지정 여부",
      "blocks_core_answer": true,
      "changes_answer": "해당 토지에 행위제한이 있는 지역·지구가 지정되어 있지 않다면 내용이 없는 것이 정상(누락 아님)이고, 지정되어 있다면 누락일 수 있어 결론이 달라짐."
    },
    {
      "fact": "A 문의: 신청 시 '행위제한 내용 제외' 항목을 체크했는지 여부 (기억이 안 난다면 신청 채널 및 접수번호 등 조회 가능한 정보)",
      "blocks_core_answer": true,
      "changes_answer": "신청 시 제외 옵션을 체크했다면 정상 발급이고, 체크하지 않았는데 내용이 없다면 발급 오류(누락)일 가능성이 높아짐."
    }
  ],
  "can_answer_now": false,
  "question": "A 문의에 대해 답변드리기 위해 두 가지 정보가 필요합니다. 1) 발급받은 확인서의 토지 소재지(지번)와 해당 토지가 어떤 지역·지구로 지정되어 있는지(예: 주거지역, 개발제한구역 등)를 알려주세요. 2) 신청 당시 '행위제한 내용 제외' 항목을 체크했는지 기억나시나요? (기억이 안 나신다면 신청하신 채널과 접수번호를 알려주시면 확인 방법을 안내해 드리겠습니다.)"
}

{
  "core_conclusion": "A는 등기부 종류(전산/폐쇄)에 따라 말소사항 포함 여부가 결정되며, B는 최초 열람 후 1시간 이내라면 재열람이 가능하여 추가 수수료가 발생하지 않습니다.",
  "missing_facts": [
    {
      "fact": "A 문의 대상 부동산의 등기부가 전산등기부인지, 아니면 이미지폐쇄등기부 또는 수작업폐쇄등기부인지 여부",
      "blocks_core_answer": true,
      "changes_answer": "전산등기부는 '현재 유효사항'만 뽑을 수 있지만, 폐쇄등기부(이미지/수작업)는 '말소사항 포함' 또는 '일부사항'으로만 발급 가능하여 '현재 유효사항만 뽑기'가 불가능할 수 있음"
    }
  ],
  "can_answer_now": false,
  "question": "A 문의의 경우, 해당 부동산의 등기부가 현재 전산등기부인지, 아니면 아직 전산으로 전환되지 않은 폐쇄등기부(이미지 또는 수작업)인지 확인해 주시겠어요? (B 문의는 30분 이내 재열람이므로 추가 비용 없이 재열람 가능하다는 안내가 가능합니다.)"
}

{
  "core_conclusion": "A는 경기도 2005년 졸업으로 발급 대상이 아니며, B는 학교 유형(국립/공립/사립)에 따라 수수료가 달라지므로 학교 유형 확인이 필요합니다.",
  "missing_facts": [
    {
      "fact": "B 문의에서 언급한 중학교의 학교 유형(국립, 공립, 사립 중 어디인지)",
      "blocks_core_answer": true,
      "changes_answer": "국립학교는 수수료가 면제되지만, 공립 및 사립학교는 시·도 조례에 따라 수수료가 부과될 수 있어 무료 여부 판단이 불가능합니다."
    }
  ],
  "can_answer_now": false,
  "question": "B 문의에 대해 안내드리기 위해 확인이 필요합니다. 발급받으실 중학교가 국립학교인지, 아니면 교육감 소속의 공립 또는 사립학교인지 알려주세요."
}

{
  "core_conclusion": "A는 개별공시지가확인서 발급이 가능하며, B는 신청서(별지 제6호서식)를 제출해야 합니다.",
  "missing_facts": [],
  "can_answer_now": true,
  "question": ""
}

{
  "core_conclusion": "A는 인감증명서 사본의 유효기간(3개월)이 경과하여 사용 불가하며, B는 사업자의 현재 상태(휴업 또는 폐업)에 따라 발급받을 증명서 종류가 달라지므로 상태 확인이 필요합니다.",
  "missing_facts": [
    {
      "fact": "B의 사업자가 현재 '휴업' 상태인지 '폐업' 상태인지 여부",
      "blocks_core_answer": true,
      "changes_answer": "휴업이면 '휴업사실증명', 폐업이면 '폐업사실증명'을 발급받아야 하므로 증명서 종류가 결정되지 않음"
    }
  ],
  "can_answer_now": false,
  "question": "B 문의에 대해, 해당 사업자가 현재 '휴업' 상태인지 '폐업' 상태인지 확인 부탁드립니다. (가족에게 확인이 어렵다면, 사업자등록증명이나 홈택스 조회 등을 통해 현재 사업자 상태를 먼저 확인해 주셔야 어떤 증명을 발급받아야 하는지 안내가 가능합니다.)"
}

{
  "core_conclusion": "A는 손자로서 직계혈족이 아니므로 인터넷 발급이 불가하며, B는 가족관계증명서 발급 주체(본인)를 특정해야 신청 가능 여부가 결정됩니다.",
  "missing_facts": [
    {
      "fact": "B가 가족관계증명서를 발급받으려는 주체(본인)가 누구인지 (아버지 본인인지, B 본인인지)",
      "blocks_core_answer": true,
      "changes_answer": "발급 주체가 아버지라면 B는 직계비속(자녀)이므로 인터넷 발급이 가능하지만, 발급 주체가 B 본인이라면 형제(형제자매)는 직계혈족이 아니므로 인터넷 발급이 불가능합니다."
    }
  ],
  "can_answer_now": false,
  "question": "B 문의에 대해, 가족관계증명서를 발급받으려는 주체(본인)가 아버지 본인인지 아니면 B 본인인지 확인 부탁드립니다."
}

{
  "core_conclusion": "A 문의는 이의신청 마감일 계산을 위해 '결정 통지일'과 '입원 종료일(사유 소멸일)'이 필요하며, B 문의는 국적 상실·국외 이주 시 수급권 상실(기초연금법 제17조)과 단순 국외 체류 시 지급 정지(기초연금법 제16조)의 법적 근거를 안내한다.",
  "missing_facts": [
    {
      "fact": "A의 기초연금 결정 통지(알게 된) 날짜",
      "blocks_core_answer": true,
      "changes_answer": "이의신청 기간은 처분이 있음을 안 날부터 90일 이내이므로, 이 날짜가 없으면 기본 마감일을 계산할 수 없습니다."
